import { accountApi, accountConfig, discoverAccountConfig } from './account.js';
import { isAgeConfirmed, r18Visible, readR18Visible, setR18Visible } from './theme-access.js';
import { canonicalCard } from './account-library.js';

const root = document.querySelector('#market-app');
const authDialog = document.querySelector('#market-auth');
const authStatus = document.querySelector('#market-auth-status');
let authBusy = false;
const qs = new URLSearchParams(location.search);
const state = { account: null, user: null, sets: [], customCards: [], drafts: [], items: [], ownerItems: [], detail: null, detailSeq: 0, tab: qs.has('publish') ? 'owner' : 'discover', search: '', category: '', audience: '', offset: 0, hasMore: false, loading: false, error: '', status: '', epoch: 0, authGeneration: 0, authUserId: null, busy: false, publishing: qs.has('publish'), publishSetId: qs.get('publish') || '', publishStep: 'form', publishDraft: null, detailPreviousFocus: null };
const MARKET_AUTH_KEY = 'mingle.cards.marketplace-auth.v1';
const esc = (value) => String(value ?? '').replace(/[&<>'"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[ch]));
const enc = (value) => encodeURIComponent(String(value));
const modeLabel = (value) => ({ group: 'みんなとミングる', solo: '自分とミングる', both: 'みんな / 自分' }[value] || value || '');
const catLabel = (value) => ({ self: '自己理解', relationship: '恋愛・夫婦', friends: '友人', family: '家族', work: '仕事', sports: 'スポーツ', 'first-meeting': '初対面', roleplay: 'なりきり', adult: 'R18' }[value] || value || '');
function snapshotAccount(me) { const account = { ...(me?.account || {}), user: me?.user || null, enabled: accountConfig.enabled, authReady: true, ageConfirmedAt: me?.account?.adultConfirmedAt || me?.account?.ageConfirmedAt || null }; readR18Visible(account, window.sessionStorage); state.account = account; state.user = me?.user || null; state.sets = Array.isArray(me?.sets) ? me.sets : []; state.customCards = Array.isArray(me?.customCards) ? me.customCards : Array.isArray(me?.account?.customCards) ? me.account.customCards : []; state.drafts = Array.isArray(me?.drafts) ? me.drafts : Array.isArray(me?.setDrafts) ? me.setDrafts : []; return account; }
function showR18() { return r18Visible(state.account); }
function query(extra = {}) { const p = new URLSearchParams({ limit: '20', offset: String(state.offset), ...(state.search ? { search: state.search } : {}), ...(state.category ? { category: state.category } : {}), ...(state.audience ? { audience: state.audience } : {}), ...(showR18() ? { showR18: 'true' } : {}), ...extra }); return p.toString(); }
function adultAllowed(item) { return item?.adult === true || item?.adultOnly === true; }
function visible(item) { return !adultAllowed(item) || showR18(); }
function readySets() { const draftIds = new Set(state.drafts.map((draft) => draft.sourceSetId).filter(Boolean)); return state.sets.map((set) => { const ids = Array.isArray(set.card_ids) ? set.card_ids : []; const cards = ids.map((id) => canonicalCard(id, state.customCards)).filter(Boolean); const complete = ids.length >= 6 && ids.length <= 40 && cards.length === ids.length && !draftIds.has(set.id); const adult = cards.some((card) => card.r18 === true); return complete ? { ...set, cardCount: ids.length, cards, adult, adultOnly: adult, name: adult && !showR18() ? 'R18テーマ' : (set.name || '無題のセット') } : null; }).filter(Boolean).filter((set) => !set.adult || showR18()); }
function selectedSource() { return readySets().find((set) => set.id === state.publishSetId) || null; }
function existingPublishListing(sourceId) { return state.ownerItems.find((item) => item.sourceSetId === sourceId) || null; }
function ensurePublishDraft(row) { if (!row || state.publishStep === 'review' || state.publishDraft) return; const previous = existingPublishListing(row.id); state.publishDraft = { name: previous?.name || row.name || '', description: previous?.description || '', category: previous?.category || 'self', publisherName: previous?.publisherName || state.user?.displayName || state.user?.user_metadata?.display_name || '匿名' }; }
function clearMarketplacePrivate() { state.authGeneration += 1; state.epoch += 1; state.busy = false; state.loading = false; state.sets = []; state.customCards = []; state.drafts = []; state.ownerItems = []; state.items = []; state.detail = null; state.publishDraft = null; state.publishSetId = ''; state.publishing = false; state.status = ''; state.error = ''; state.offset = 0; state.hasMore = false; }
function saveMarketIntent(type, id = '') { try { const createdAt = Date.now(); sessionStorage.setItem(MARKET_AUTH_KEY, JSON.stringify({ type, id, createdAt, expiresAt: createdAt + 30 * 60 * 1000 })); } catch {} }
function readMarketIntent() { try { const value = JSON.parse(sessionStorage.getItem(MARKET_AUTH_KEY) || 'null'); if (!value || value.expiresAt < Date.now() || !['detail','publish','owner'].includes(value.type) || (value.type !== 'owner' && !value.id)) { sessionStorage.removeItem(MARKET_AUTH_KEY); return null; } return value; } catch { return null; } }
function clearMarketIntent() { try { sessionStorage.removeItem(MARKET_AUTH_KEY); } catch {} }
function formatError(error) { if (error?.status === 503) return 'マーケットプレイスは準備中です。しばらくしてから再試行してください。'; if (error?.status === 401) return 'ログインが必要です。'; if (error?.status === 403) return '年齢確認と「R18を表示する」が必要です。'; if (error?.status === 404) return 'この公開テーマは見つからないか、停止されています。'; if (error?.status === 409) return '元のテーマが変更されています。内容を確認してから再試行してください。'; if (error?.status === 400) return '入力内容を確認してください。'; return '読み込みに失敗しました。再試行してください。'; }
async function loadMe(expectedUserId = null) { const gen = state.authGeneration; try { const me = await accountApi.me(); if (gen !== state.authGeneration) return false; const nextId = me?.user?.id || null; if (expectedUserId && nextId !== expectedUserId) return false; if (state.authUserId && state.authUserId !== nextId) clearMarketplacePrivate(); state.authUserId = nextId; snapshotAccount(me); return true; } catch (error) { if (gen !== state.authGeneration) return false; if (error?.status === 401) clearMarketplacePrivate(); state.authUserId = null; state.user = null; state.account = { user: null, enabled: accountConfig.enabled, authReady: true }; state.error = formatError(error); return false; } }
async function loadCatalog(reset = true) { const token = ++state.epoch; const gen = state.authGeneration; const userId = state.authUserId; if (reset) { state.offset = 0; state.items = []; state.hasMore = false; } state.loading = true; state.error = ''; render(); try { const result = await accountApi.marketplaceList(query()); if (token !== state.epoch || gen !== state.authGeneration || userId !== state.authUserId) return; const rows = Array.isArray(result.items) ? result.items.filter(visible) : []; state.items = reset ? rows : state.items.concat(rows); state.offset = Number(result.offset || state.offset) + rows.length; state.hasMore = rows.length >= Number(result.limit || 20); } catch (error) { if (token === state.epoch && gen === state.authGeneration) state.error = formatError(error); } finally { if (token === state.epoch && gen === state.authGeneration) { state.loading = false; render(); } } }
async function loadOwner() { const token = ++state.epoch; const gen = state.authGeneration; const userId = state.authUserId; state.loading = true; state.error = ''; render(); try { const result = await accountApi.marketplaceOwner(showR18() ? 'showR18=true' : ''); if (token !== state.epoch || gen !== state.authGeneration || userId !== state.authUserId) return; state.ownerItems = Array.isArray(result.items) ? result.items.filter(visible) : []; if (state.publishing && state.publishSetId) state.publishDraft = null; } catch (error) { if (token === state.epoch && gen === state.authGeneration) state.error = formatError(error); } finally { if (token === state.epoch && gen === state.authGeneration) { state.loading = false; render(); } } }
function card(item) { if (!visible(item)) return ''; const title = adultAllowed(item) && !showR18() ? 'R18テーマ' : item.name; return `<article class="market-card" data-listing-id="${esc(item.id)}"><h2>${esc(title)}</h2><p>${esc(item.description || '')}</p><div class="market-meta"><span>${esc(item.publisherName || '匿名')}</span><span>${Number(item.cardCount || 0)}問</span><span>${esc(modeLabel(item.audience))}</span><span>無料</span><span>取り込み ${Number(item.importCount || 0)}</span><span>いいね ${Number(item.likeCount || 0)}</span></div><div class="market-actions"><button class="secondary-button" data-action="detail" data-id="${esc(item.id)}">詳細を見る</button><button class="text-button" data-action="like" data-id="${esc(item.id)}" aria-pressed="${item.likedByMe === true}">${item.likedByMe === true ? 'いいね済み' : 'いいね'}</button></div></article>`; }
function controls() { const categories = ['self','relationship','friends','family','work','sports','first-meeting','roleplay', ...(showR18() ? ['adult'] : [])]; return `<div class="market-controls"><label>検索<input data-field="search" value="${esc(state.search)}" placeholder="テーマ名・説明"></label><label>カテゴリ<select data-field="category"><option value="">すべて</option>${categories.map((x) => `<option value="${x}" ${state.category === x ? 'selected' : ''}>${catLabel(x)}</option>`).join('')}</select></label><label>モード<select data-field="audience"><option value="">すべて</option><option value="group" ${state.audience === 'group' ? 'selected' : ''}>みんなとミングる</option><option value="solo" ${state.audience === 'solo' ? 'selected' : ''}>自分とミングる</option><option value="both" ${state.audience === 'both' ? 'selected' : ''}>両方</option></select></label><button class="primary-button" data-action="search">検索</button></div>`; }
function detailDialog() { const item = state.detail; if (!item) return ''; const adult = adultAllowed(item); const title = adult && !showR18() ? 'R18テーマ' : item.name; const previews = (item.preview || []).filter((p) => !p.r18 || showR18()).slice(0, 3); return `<dialog class="market-detail"><button class="dialog-close" data-action="close-detail" aria-label="閉じる">×</button><h2>${esc(title)}</h2><p>${esc(adult && !showR18() ? '表示には年齢確認と明示設定が必要です。' : item.description || '')}</p><div class="market-meta"><span>${esc(item.publisherName || '匿名')}</span><span>${Number(item.cardCount || 0)}問</span><span>${esc(modeLabel(item.audience))}</span></div><div class="market-preview">${previews.length ? previews.map((p) => `<p>${esc(p.text)}</p>`).join('') : '<p>プレビューはありません。</p>'}</div><div class="market-actions"><button class="primary-button" data-action="import" data-id="${esc(item.id)}" ${state.busy ? 'disabled' : ''}>${item.importedByMe ? 'マイセットを開く' : 'ライブラリへ追加'}</button><button class="text-button" data-action="like" data-id="${esc(item.id)}" aria-pressed="${item.likedByMe === true}">${item.likedByMe ? 'いいね済み' : 'いいね'}</button></div>${state.error ? `<p class="market-error" role="alert">${esc(state.error)}</p>` : ''}${state.status ? `<p class="market-status" role="status">${esc(state.status)}</p>` : ''}<p class="market-status">公開テーマのコピーをあなたのライブラリに作成します。元の公開テーマが後から変わっても、取り込んだ内容は変わりません。</p></dialog>`; }
function publishView() { const sets = readySets(); const row = selectedSource(); if (!row) return `<section class="market-form"><h2>テーマを公開</h2><label>公開するテーマ<select data-field="publish-source" required><option value="">選択してください</option>${sets.map((set) => `<option value="${esc(set.id)}">${esc(set.name)}（${set.cardCount}問）</option>`).join('')}</select></label>${sets.length ? '<p class="market-status">質問は保存済みテーマからコピーされます。</p>' : '<p class="market-error">公開できる6〜40問の完成済みテーマがありません。</p>'}<button class="text-button" data-action="publish-cancel">キャンセル</button></section>`; ensurePublishDraft(row); const count = row.cardCount; const audience = row.audience || 'group'; const order = row.question_order || row.questionOrder || 'shuffle'; const cats = ['self','relationship','friends','family','work','sports','first-meeting','roleplay', ...(showR18() ? ['adult'] : [])]; if (state.publishStep === 'review') return `<section class="market-form"><h2>公開内容の確認</h2><p><strong>${esc(state.publishDraft.name)}</strong> / ${esc(catLabel(state.publishDraft.category))}</p><p>${esc(state.publishDraft.description)}</p><p>公開者名義：${esc(state.publishDraft.publisherName || '匿名')}</p><p>${count}問・${esc(modeLabel(audience))}・${esc(order === 'fixed' ? '固定順' : 'シャッフル')}</p><div class="market-preview">${row.cards.slice(0, 3).map((card) => `<p>${esc(card.text)}</p>`).join('')}</div><p>他の利用者がこのテーマをライブラリへコピーできます。</p><div class="market-actions"><button class="primary-button" data-action="publish-confirm" ${state.busy ? 'disabled' : ''}>無料で公開する</button><button class="text-button" data-action="publish-edit">戻る</button></div></section>`; return `<section class="market-form"><h2>テーマを公開</h2><label>公開名<input data-field="publish-name" maxlength="80" value="${esc(state.publishDraft?.name || row.name || '')}" required></label><label>説明<input data-field="publish-description" maxlength="500" value="${esc(state.publishDraft?.description || '')}"></label><label>カテゴリ<select data-field="publish-category" required>${cats.map((x) => `<option value="${x}" ${state.publishDraft?.category === x ? 'selected' : ''}>${catLabel(x)}</option>`).join('')}</select></label><label>公開者名<input data-field="publish-publisher" maxlength="40" value="${esc(state.publishDraft?.publisherName || state.user?.displayName || state.user?.user_metadata?.display_name || '匿名')}"></label><p class="market-meta">${count}問・${esc(modeLabel(audience))}・${esc(order === 'fixed' ? '固定順' : 'シャッフル')}</p><button class="primary-button" data-action="publish-review">内容を確認</button><button class="text-button" data-action="publish-cancel">キャンセル</button></section>`; }
function ownerView() { if (!state.user) return `<section class="market-form"><h2>自分の公開テーマ</h2><p>公開テーマの管理にはログインが必要です。</p><button class="primary-button" data-action="market-login">ログイン・新規登録</button></section>`; return `<section class="market-owner"><div class="market-actions"><button class="primary-button" data-action="new-publish">テーマを公開</button></div>${state.ownerItems.length ? state.ownerItems.map((row) => `<article class="market-owner-row"><div><strong>${esc(adultAllowed(row) && !showR18() ? 'R18テーマ' : row.name)}</strong><div class="market-meta"><span>${row.withdrawn === true ? '停止中' : '公開中'}</span><span>${Number(row.importCount || 0)}人が追加</span><span>いいね ${Number(row.likeCount || 0)}</span></div></div><div class="market-actions">${row.sourceSetId ? `<a class="text-button" href="?publish=${enc(row.sourceSetId)}">${row.withdrawn === true ? '再公開' : '更新'}</a>` : ''}${row.withdrawn !== true ? `<button class="text-button" data-action="withdraw" data-id="${esc(row.id)}">公開停止</button>` : ''}</div></article>`).join('') : '<p class="market-empty">公開したテーマはありません。</p>'}</section>`; }
function render() { if (!root) return; const auth = state.user ? `<span>${esc(state.user.displayName || state.user.user_metadata?.display_name || state.user.email || 'ログイン中')}</span>` : '<span>ゲスト</span>'; const r18Control = isAgeConfirmed(state.account) ? `<label class="market-login-toggle"><input type="checkbox" data-action="r18-toggle" ${showR18() ? 'checked' : ''}> R18を表示する</label>` : ''; root.innerHTML = `<section class="market-hero"><div><h1>マーケットプレイス</h1><p>みんなのテーマで、会話を広げよう。無料で利用できます。</p></div><div class="market-actions">${auth}</div></section>${state.status ? `<p class="market-status">${esc(state.status)}</p>` : ''}<div class="market-tabs"><button class="secondary-button" data-action="tab" data-tab="discover" aria-selected="${state.tab === 'discover'}">テーマを探す</button><button class="secondary-button" data-action="tab" data-tab="owner" aria-selected="${state.tab === 'owner'}">自分の公開テーマ</button>${r18Control}</div>${state.tab === 'discover' ? `${controls()}${state.error ? `<p class="market-error">${esc(state.error)} <button class="text-button" data-action="retry">再試行</button></p>` : state.loading ? '<p class="market-status">読み込み中…</p>' : state.items.length ? `<section class="market-grid">${state.items.map(card).join('')}</section>${state.hasMore ? '<button class="secondary-button market-more" data-action="more">もっと見る</button>' : ''}` : '<p class="market-empty">公開テーマはありません。</p>'}` : `${state.error ? `<p class="market-error">${esc(state.error)}</p>` : ''}${state.publishing ? publishView() : ownerView()}`}${detailDialog()}`; const headerButton = document.querySelector('[data-action="market-login"], [data-action="market-logout"]'); if (headerButton) { headerButton.textContent = state.user ? 'ログアウト' : 'ログイン'; headerButton.dataset.action = state.user ? 'market-logout' : 'market-login'; } const dialog = root.querySelector('.market-detail'); if (dialog && state.detail && !dialog.open) { dialog.addEventListener('cancel', (event) => { event.preventDefault(); state.detail = null; render(); }); dialog.showModal(); } }
function syncAuthProviders() { const google = document.querySelector('[data-action="market-google"]'); const form = document.querySelector('#market-otp'); if (google) google.hidden = accountConfig.google !== true; if (form) form.hidden = accountConfig.emailOtp === false; }
function openAuth() { syncAuthProviders(); if (!accountConfig.enabled) { authStatus.textContent = '現在ログイン機能を利用できません。'; } else authStatus.textContent = ''; authDialog?.showModal(); }
async function refresh() { await loadMe(); const intent = state.user ? readMarketIntent() : null; if (intent) { if (intent.type === 'detail') { try { state.detail = await accountApi.marketplaceDetail(intent.id, showR18() ? 'showR18=true' : ''); } catch {} } if (intent.type === 'publish') { state.tab = 'owner'; state.publishing = true; state.publishSetId = intent.id; } if (intent.type === 'owner') state.tab = 'owner'; clearMarketIntent(); } render(); if (state.tab === 'owner' && state.user) await loadOwner(); else await loadCatalog(true); }
async function doLike(id, button) { if (!state.user) return openAuth(); if (state.busy) return; const gen = state.authGeneration; const userId = state.authUserId; state.busy = true; button.disabled = true; try { const item = state.items.find((x) => x.id === id) || state.detail; await accountApi.marketplaceLike({ listingId: id, liked: item?.likedByMe !== true, showR18: showR18() }); if (gen !== state.authGeneration || userId !== state.authUserId) return; state.status = ''; await loadCatalog(true); if (state.detail && gen === state.authGeneration && userId === state.authUserId) { const refreshed = await accountApi.marketplaceDetail(id, showR18() ? 'showR18=true' : ''); if (gen === state.authGeneration && userId === state.authUserId && (!adultAllowed(refreshed) || showR18())) state.detail = refreshed; } } catch (error) { if (gen === state.authGeneration) state.error = formatError(error); } finally { if (gen === state.authGeneration) { state.busy = false; render(); } } }
async function doImport(id) { if (!state.user) return openAuth(); if (state.busy) return; const gen = state.authGeneration; const userId = state.authUserId; state.busy = true; render(); try { await accountApi.marketplaceImport({ listingId: id, showR18: showR18() }); if (gen !== state.authGeneration || userId !== state.authUserId) return; state.status = 'ライブラリに追加しました。'; if (state.detail) state.detail = { ...state.detail, importedByMe: true }; await loadCatalog(true); } catch (error) { if (gen === state.authGeneration) state.error = formatError(error); } finally { if (gen === state.authGeneration) { state.busy = false; render(); } } }
async function doPublish() { if (state.busy) return; const row = selectedSource(); if (!row || !state.publishDraft || !state.publishDraft.name?.trim()) { state.error = '公開名を入力してください。'; render(); return; } const gen = state.authGeneration; const userId = state.authUserId; state.busy = true; state.error = ''; render(); try { await accountApi.marketplacePublish({ setId: row.id, name: state.publishDraft.name.trim(), description: state.publishDraft.description || '', category: state.publishDraft.category, publisherName: state.publishDraft.publisherName || '匿名', audience: row.audience || 'group', questionOrder: row.question_order || row.questionOrder || 'shuffle', showR18: showR18() }); if (gen !== state.authGeneration || userId !== state.authUserId) return; state.publishSetId = ''; state.publishing = false; state.publishStep = 'form'; state.tab = 'owner'; await loadOwner(); } catch (error) { if (gen === state.authGeneration) state.error = formatError(error); } finally { if (gen === state.authGeneration) { state.busy = false; render(); } } }
async function authSubmit(event) { event.preventDefault(); if (authBusy) return; const form = event.currentTarget; const emailInput = form.querySelector('input[type=email]'); const tokenInput = form.querySelector('[data-otp-token]'); const submit = form.querySelector('[data-otp-submit]'); const resend = form.querySelector('[data-action="market-otp-resend"]'); const change = form.querySelector('[data-action="market-otp-change"]'); const token = tokenInput?.value.trim(); const email = emailInput?.value.trim(); if (!email || (!token && !emailInput.checkValidity())) return; authBusy = true; if (submit) submit.disabled = true; try { if (!token) { await accountApi.sendOtp(email); tokenInput.hidden = false; tokenInput.required = true; form.querySelector('[data-otp-label]')?.removeAttribute('hidden'); if (submit) submit.textContent = 'ログインする'; if (resend) resend.hidden = false; if (change) change.hidden = false; authStatus.textContent = '確認コードを送信しました。'; } else { await accountApi.verifyOtp(email, token); emailInput.value = ''; tokenInput.value = ''; authDialog.close(); await refresh(); } } catch (error) { authStatus.textContent = formatError(error); } finally { authBusy = false; if (submit) submit.disabled = false; } }
root?.addEventListener('input', (event) => { const f = event.target.dataset.field; if (f === 'search') state.search = event.target.value; const keys = { 'publish-name': 'name', 'publish-description': 'description', 'publish-category': 'category', 'publish-publisher': 'publisherName' }; if (keys[f]) { state.publishDraft ||= {}; state.publishDraft[keys[f]] = event.target.value; } });
root?.addEventListener('change', async (event) => { const f = event.target.dataset.field; if (f === 'category') { state.category = event.target.value; await loadCatalog(true); } if (f === 'audience') { state.audience = event.target.value; await loadCatalog(true); } if (f === 'publish-source') { state.publishSetId = event.target.value; state.publishDraft = null; state.publishStep = 'form'; render(); } if (event.target.dataset.action === 'r18-toggle') { if (!isAgeConfirmed(state.account)) return; state.authGeneration += 1; state.busy = false; state.detailSeq += 1; setR18Visible(state.account, event.target.checked, window.sessionStorage); state.detail = null; state.category = ''; if (!event.target.checked) { state.ownerItems = state.ownerItems.filter((item) => !adultAllowed(item)); if (state.publishSetId && !selectedSource()) { state.publishSetId = ''; state.publishing = false; state.publishDraft = null; } } render(); if (state.tab === 'owner' && state.user) await loadOwner(); else await loadCatalog(true); } if (f === 'publish-show-r18' && state.publishDraft) state.publishDraft.showR18 = event.target.checked; });
root?.addEventListener('click', async (event) => { const el = event.target.closest('[data-action]'); if (!el) return; const action = el.dataset.action; if (action === 'tab') { state.tab = el.dataset.tab; state.publishSetId = ''; state.publishDraft = null; state.publishStep = 'form'; state.publishing = false; state.error = ''; render(); if (state.tab === 'owner' && state.user) await loadOwner(); else if (state.tab === 'discover') await loadCatalog(true); } else if (action === 'search' || action === 'retry') await loadCatalog(true); else if (action === 'more') await loadCatalog(false); else if (action === 'market-login') openAuth(); else if (action === 'detail') { const gen = state.authGeneration; const userId = state.authUserId; const detailSeq = ++state.detailSeq; try { state.detailPreviousFocus = { id: el.dataset.id }; const detail = await accountApi.marketplaceDetail(el.dataset.id, showR18() ? 'showR18=true' : ''); if (detailSeq !== state.detailSeq || gen !== state.authGeneration || userId !== state.authUserId || (adultAllowed(detail) && !showR18())) return; state.detail = detail; render(); root.querySelector('.market-detail')?.querySelector('button')?.focus(); } catch (error) { if (detailSeq === state.detailSeq && gen === state.authGeneration) { state.error = formatError(error); render(); } } } else if (action === 'close-detail') { state.detailSeq += 1; state.detail = null; render(); document.querySelector(`[data-action="detail"][data-id="${CSS.escape(state.detailPreviousFocus?.id || '')}"]`)?.focus(); } else if (action === 'like') await doLike(el.dataset.id, el); else if (action === 'import') { if (state.detail?.importedByMe) location.href = '/?library=1'; else await doImport(el.dataset.id); } else if (action === 'new-publish') { state.publishSetId = ''; state.publishing = true; state.publishStep = 'form'; state.publishDraft = null; render(); } else if (action === 'publish-cancel') { state.publishSetId = ''; state.publishing = false; state.publishStep = 'form'; state.publishDraft = null; render(); } else if (action === 'publish-review') { state.publishDraft ||= {}; state.publishDraft.name = root.querySelector('[data-field="publish-name"]')?.value.trim() || ''; state.publishDraft.description = root.querySelector('[data-field="publish-description"]')?.value.trim() || ''; state.publishDraft.category = root.querySelector('[data-field="publish-category"]')?.value || ''; state.publishDraft.publisherName = root.querySelector('[data-field="publish-publisher"]')?.value.trim() || '匿名'; if (!state.publishDraft.name) { state.error = '公開名を入力してください。'; render(); return; } state.publishStep = 'review'; render(); } else if (action === 'publish-edit') { state.publishStep = 'form'; render(); } else if (action === 'publish-confirm') await doPublish(); else if (action === 'withdraw') { const gen = state.authGeneration; state.busy = true; render(); if (confirm('このテーマの公開を停止しますか？取り込み済みのコピーは残ります。')) { try { await accountApi.marketplaceWithdraw({ listingId: el.dataset.id }); if (gen === state.authGeneration) await loadOwner(); } catch (error) { if (gen === state.authGeneration) state.error = formatError(error); } } state.busy = false; render(); } });
document.addEventListener('click', async (event) => { const action = event.target.closest('[data-action]')?.dataset.action; if (action === 'market-login') openAuth(); if (action === 'market-logout') { clearMarketIntent(); try { await accountApi.logout(); } catch (error) { state.error = formatError(error); render(); } } if (action === 'market-auth-close') { clearMarketIntent(); authDialog.close(); } if (action === 'market-otp-resend') { const form = document.querySelector('#market-otp'); if (form) { const input = form.querySelector('input[type=email]'); input?.focus(); form.querySelector('[data-otp-token]').value = ''; await authSubmit({ preventDefault() {}, currentTarget: form }); } } if (action === 'market-otp-change') { const form = document.querySelector('#market-otp'); if (form) { const tokenInput = form.querySelector('[data-otp-token]'); form.querySelector('input[type=email]').value = ''; tokenInput.value = ''; tokenInput.hidden = true; tokenInput.required = false; form.querySelector('[data-otp-label]')?.setAttribute('hidden', ''); form.querySelector('[data-otp-submit]').textContent = '確認コードを送る'; form.querySelector('[data-action="market-otp-resend"]').hidden = true; form.querySelector('[data-action="market-otp-change"]').hidden = true; form.querySelector('input[type=email]').focus(); } } }); document.querySelector('#market-otp')?.addEventListener('submit', authSubmit); document.querySelector('[data-action="market-google"]')?.addEventListener('click', async () => { try { saveMarketIntent(state.detail ? 'detail' : state.publishing ? 'publish' : 'owner', state.detail?.id || state.publishSetId || ''); await accountApi.google(); } catch (error) { authStatus.textContent = formatError(error); } });
