accountApi.onAuthStateChange?.((event, session) => { setTimeout(async () => { const nextId = session?.user?.id || null; const previousId = state.authUserId || state.user?.id || null; const identityChanged = Boolean(previousId && previousId !== nextId); if (event === 'SIGNED_OUT' || identityChanged) { clearMarketIntent(); clearMarketplacePrivate(); state.authUserId = nextId; state.user = null; state.account = { user: null, enabled: accountConfig.enabled, authReady: true }; try { const storage = window.sessionStorage; storage?.removeItem('mingle.cards.r18-display.v1'); } catch {} } const gen = state.authGeneration; await loadMe(nextId); if (gen !== state.authGeneration) return; render(); if (state.tab === 'owner' && state.user) await loadOwner(); else await loadCatalog(true); }, 0); });
